        countArray[word1.charAt(i) - 'A']++;
    }
    for (int i = 0; i < word2.length(); i++) {
        countArray[word2.charAt(i) - 'A']++;
        if (countArray[word2.charAt(i) - 'A'] == 2) {
            count++;
        }
    }
    return count;
}

