public int search(int[] nums, int target) {
        int left = 0, right = nums.length - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] == target) {
                return mid;
            }

            if (nums[mid] <= nums[right]) {
                // Right half is sorted
                if (nums[mid] < target && target <= nums[right]) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            } else {
                // Left half is sorted
                if (nums[left] <= target && target < nums[mid]) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
        }

        return -1;
    }

public int search(int[] nums, int target) {
    int low = 0, hi = nums.length - 1;
    if(nums[low] <= nums[hi]) {
        return binarySearch(nums, low, hi, target);
    }
    while(low < hi) {
        int mid = (low + hi) / 2;
        if(nums[mid] > nums[hi]) {
            low = mid + 1;
        } else {
            hi = mid;
        }
    }
    int min = low;
    low = 0;
    hi = nums.length - 1;
    if(nums[min] <= nums[hi]) {
        return binarySearch(nums, low, hi, target);
    }
    while(low < hi) {
        int mid = (low + hi) / 2;
        if(nums[mid] <= nums[hi]) {
            hi = mid;
        } else {
            low = mid + 1;
        }
    }
    int piv = nums[low];
    if(target >= nums[min] && target <= piv) {
        return binarySearch(nums, min, piv, target);
    } else {
        return binarySearch(nums, piv + 1, nums.length - 1, target);
    }
}

