public double trimMean(int[] arr) {
        Arrays.sort(arr);
        int n = arr.length;
        int threshold = (int) (n * 0.05);
        int sum = 0;

        for (int i = threshold; i < n - threshold; i++) {
            sum += arr[i];
        }

        return (double) sum / (n - 2 * threshold);
    }

public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int start = arr.length / 20;
    int end = arr.length - start - 1;
    double sum = 0;
    for (int i = start; i <= end; i++) {
        sum += arr[i];
    }
    return sum / (end - start + 1);
}

public double trimMean(int[] arr) {
        List<Integer> data = new ArrayList<>();
        int n = arr.length;

        // Add all elements to the list
        for(int i : arr) {
            data.add(i);
        }

        // Sort the list
        Collections.sort(data);

        int k = n * 5 / 100;

        // Remove the smallest 5% and largest 5%
        List<Integer> trimmedData = data.subList(k, n - k);

        int sum = 0;
        for(int i : trimmedData) {
            sum += i;
        }

        // Calculate the mean with error within 10^-5
        return Math.round((double) sum / trimmedData.size() * 100000) / 100000;
    }

