public boolean canArrange(int[] arr, int k) {
    HashSet<Integer> seen = new HashSet<>();
    for (int num : arr) {
        int mod = num % k;
        if (mod == 0 || seen.contains(k - mod))
            return true;
        seen.add(mod);
    }
    return false;
}

public boolean canArrange(int[] arr, int k) {
        int[] counts = new int[k];
        for (int num : arr) {
            counts[num % k]++;
        }
        int count = 0;
        for (int i = 0; i < k; i++) {
            count += counts[i] % 2;
        }
        return count <= 1;
    }

public boolean canArrange(int[] arr, int k) {
    int divisors[] = new int[k];
    for (int i : arr) {
        int remainder = i % k;
        divisors[remainder]++;
    }
    int oddCount = 0;
    for (int i = 1; i <= k / 2; i++) {
        if (divisors[i] != divisors[k - i]) {
            return false;
        }
        if (i % 2 == 1) {
            oddCount++;
        }
    }
    return oddCount % 2 == 0;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }

    HashMap<Integer, Integer> remainderCounts = new HashMap<>();
    for (int num : arr) {
        int remainder = num % k;
        remainderCounts.put(remainder, remainderCounts.getOrDefault(remainder, 0) + 1);
    }

    int oddCount = 0;
    for (int remainder : remainderCounts.values()) {
        if (remainder % 2 != 0) {
            oddCount++;
        }
    }

    return oddCount % 2 == 0;
}

public boolean canArrange(int[] arr, int k) {
    int[] count = new int[k];
    for (int num : arr) {
        int remainder = num % k;
        count[remainder]++;
    }

    // Check if the count of reminders for all pairs is even
    for (int key : count) {
        if (key % 2 != 0) {
            return false;
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<List<Integer>>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }
    Map<Integer, Integer> parentMap = new HashMap<>();
    buildParentMap(0, -1, graph, parentMap);
    return minTime(0, hasApple, parentMap);
}

private int minTime(int node, boolean[] hasApple, Map<Integer, Integer> parentMap) {
    int time = 0;
    boolean hasApple = false;
    for (int neighbor : graph.get(node)) {
        if (neighbor != parentMap.get(node)) {
            int childTime = minTime(neighbor, hasApple, parentMap);
            if (childTime > 0 || hasApple) {
                time += childTime + 2;
                hasApple = true;
            }
        }
    }
    return hasApple ? time : 0;
}

private void buildParentMap(int node, int parent, List<List<Integer>> graph, Map<Integer, Integer> parentMap) {
    parentMap.put(node, parent);
    for (int neighbor : graph.get(node)) {
        if (neighbor != parent) {
            buildParentMap(neighbor, node, graph, parentMap);
        }
    }
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] adjList = new List[n];
    for (int i = 0; i < n; i++) {
        adjList[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        adjList[edge[0]].add(edge[1]);
        adjList[edge[1]].add(edge[0]);
    }
    return dfs(0, adjList, hasApple, new boolean[n]);
}

private int dfs(int node, List<Integer>[] adjList, boolean[] hasApple, boolean[] visited) {
    visited[node] = true;
    int time = 0;
    for (int neighbor : adjList[node]) {
        if (!visited[neighbor]) {
            time += dfs(neighbor, adjList, hasApple, visited);
        }
    }
    if (time > 0 || (hasApple[node] && neighbor != 0)) {
        return time + 2;
    }
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] adj = new List[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        adj[edge[0]].add(edge[1]);
        adj[edge[1]].add(edge[0]);
    }
    // boolean[][] visited = new boolean[n][n];
    return traverse(adj, 0, 0, hasApple, 0);
}

private int traverse(List<Integer>[] adj, int cur, int prev, boolean[] hasApple, int time) {
    int currentTime = time;
    for (int next : adj[cur]) {
        if (next != prev) {
            currentTime = Math.max(currentTime, traverse(adj, next, cur, hasApple, currentTime + 1));
        }
    }
    return currentTime == time && !hasApple[cur] ? time : currentTime + 1;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    boolean[] visited = new boolean[n];
    Map<Integer, List<Integer>> graph = buildGraph(n, edges);
    return calculateAndReturnTime(visited, graph, 0, hasApple);
}

private boolean isThereAnApple(int n, int[][] edges, boolean[] hasApple, int p) {
    List<Integer> neighbors = graph.get(n);
    neighbors.add(p);

    boolean foundApple = false;
    for (Integer neighbor : neighbors) {
        if (hasApple[neighbor]) {
            foundApple = true;
        }
        if (neighbor != p && isThereAnApple(neighbor, edges, hasApple, n)) {
            foundApple = true;
            break;
        }
    }

    return foundApple;
}

private Map<Integer, List<Integer>> buildGraph(int n, int[][] edges) {
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int i = 0; i < n; i++) {
        graph.put(i, new ArrayList<>());
    }

    for (int[] edge : edges) {
        int from = edge[0], to = edge[1];
        graph.get(from).add(to);
        graph.get(to).add(from);
    }

    return graph;
}

private int calculateAndReturnTime(boolean[] visited, Map<Integer, List<Integer>> graph, int u, boolean[] hasApple) {
    visited[u] = true;
    int totalMicros = 0;

    List<Integer> neighbors = graph.get(u);
    for (Integer neighbor : neighbors) {
        if (!visited[neighbor]) {
            if (isThereAnApple(neighbor, edges, hasApple, u)) {
                totalMicros += 2; // Round trip
            }
        }
        totalMicros += calculateAndReturnTime(visited, graph, neighbor, hasApple);
    }

    return totalMicros;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // pre-processing: build the graph in adjacency list form
    List<List<Integer>> adjacencyList = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        adjacencyList.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        adjacencyList.get(edge[0]).add(edge[1]);
        adjacencyList.get(edge[1]).add(edge[0]);
    }
    // pre-processing: build a parent array for each node using DFS to determine the parent-child relationship
    boolean[] visited = new boolean[n];
    int[] parent = new int[n];
    dfs(adjacencyList, visited, parent);

    // process apples and record the visit time of each node
    int time = 0;
    visited[0] = true;
    ifhasApple[0] || (hasApple[1] && parent[1] == 0) || (hasApple[2] && parent[2] == 0))
        time += 2; // start with 2 since each Apple takes 2 step
    processApple(adjacencyList, visited, parent, 0);

    return time;
}

public void dfs(List<List<Integer>> adjacencyList, boolean[] visited, int[] parent) {
    for (int neighbor : adjacencyList.get(parent)) {
        if (!visited[neighbor]) {
            visited[neighbor] = true;
            parent[neighbor] = parent[0];
            dfs(adjacencyList, visited, parent);
        }
    }
}

public void processApple(List<List<Integer>> adjacencyList, boolean[] visited, int[] parent, int node) {
    for (int neighbor : adjacencyList.get(node)) {
        if (visited[neighbor]) {
            if (hasApple[neighbor]) {
                time += 2;
                processApple(adjacencyList, visited, parent, neighbor);
            }
        }
    }
}

public String sortString(String s) {
        PriorityQueue<Character> minHeap = new PriorityQueue<>();
        PriorityQueue<Character> maxHeap = new PriorityQueue<>(Comparator.reverseOrder());
        StringBuilder result = new StringBuilder();

        // Populate the heaps with characters from the string
        for (char c : s.toCharArray()) {
            if (Character.isLowerCase(c)) {
                minHeap.offer(c);
            } else {
                maxHeap.offer(c);
            }
        }

        // Continue until we have processed all characters in the string
        while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
            if (!minHeap.isEmpty()) {
                result.append(minHeap.poll());
                // Ensure we don't use the same character twice in the result unless it appears more than once
                while (!minHeap.isEmpty() && minHeap.peek() == result.charAt(result.length() - 1)) {
                    minHeap.poll();
                }
            }

            if (!maxHeap.isEmpty()) {
                result.append(maxHeap.poll());
                // Ensure we don't use the same character twice in the result unless it appears more than once
                while (!maxHeap.isEmpty() && maxHeap.peek() == result.charAt(result.length() - 1)) {
                    maxHeap.poll();
                }
            }
        }

        return result.toString();
    }

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    int[] frequency = new int[26];
    for (char c : s.toCharArray()) {
        frequency[c - 'a']++;
    }

    int closed = 0;
    while (closed < s.length()) {
        for (int i = 0; i < 26; i++) {
            if (frequency[i] > 0) {
                frequency[i]--;
                result.append((char) ('a' + i));
                closed++;
            }
        }
        for (int i = 25; i >= 0; i--) {
            if (frequency[i] > 0) {
                frequency[i]--;
                result.append((char) ('a' + i));
                closed++;
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    // Sort the string to facilitate picking characters
    char[] chars = s.toCharArray();
    Arrays.sort(chars);

    int left = 0, right = chars.length - 1;

    while (left <= right) {
        if (left == right) {
            // If there is only one character, add it directly
            result.append(chars[left]);
        } else {
            // Pick the smallest character until it appears more than once
            while (left + 1 <= right && chars[left] == chars[left + 1]) {
                left++;
            }
            // Pick the smallest character
            result.append(chars[left++]);

            // Pick the largest character until it appears more than once
            while (left <= right && chars[right] == chars[right - 1]) {
                right--;
            }
            // Pick the largest character
            result.append(chars[right--]);
        }
    }

    return result.toString();
}

public String sortString(String s) {
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
            }
        }
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    char[] sArray = s.toCharArray();
    Arrays.sort(sArray);

    int start = 0;
    int end = sArray.length - 1;

    while (start <= end) {
        if (start == end) {
            result.append(sArray[start]);
        } else {
            result.append(Arrays.stream(sArray).limit(end - start + 1).sorted((a, b) -> a - b).limit(1));
            result.append(Arrays.stream(sArray).limit(end - start + 1).sorted((a, b) -> b - a).limit(1));
        }
        start++;
        end--;
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int len = nums.length;
    int targetSum = totalSum / len;
    return dfs(nums, new boolean[len], targetSum, 0, 0, 0);
}

private boolean dfs(int[] nums, boolean[] visited, int targetSum, int start, int currentSum, int count) {
    if (count == len && currentSum == targetSum) {
        return true;
    }
    if (count == len || currentSum > targetSum || start == len) {
        return false;
    }
    for (int i = start; i < len; i++) {
        if (!visited[i]) {
            visited[i] = true;
            if (dfs(nums, visited, targetSum, i + 1, currentSum + nums[i], count + 1)) {
                return true;
            }
            visited[i] = false;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = ArrayUtils.sum(nums);
    int targetSum = totalSum / 2;

    for (int size = 1; size < nums.length / 2 + 1; size++) {
        int[] leftArr = new int[size], rightArr = new int[nums.length - size];
        for (int i = 0; i < size; i++) {
            leftArr[i] = nums[i];
        }
        for (int i = 0; i < nums.length - size; i++) {
            rightArr[i] = nums[i + size];
        }

        if (isDivisibleBy2 leftArr, targetSum) {
            if (isSumEqual(leftArr, rightArr, targetSum)) {
                return true;
            }
        }
    }
    return false;
