public boolean splitArraySameAverage(int[] nums) {
    int sum = Arrays.stream(nums).sum();
    // Helper function to check if it's possible to split with a given difference
    boolean checkDifference(int val, int[][] dp, int[] nums) {
        for (int i = dp.length - 1; i >= 0; i--) {
            if (val < 0) dp[i][val] = false; // If value is negative, it's impossible
            else if (val == 0) dp[i][val] = true; // If value is zero, it's possible
            else {
                dp[i][val] = dp[i + 1][val] || dp[i + 1][val - nums[i]];
            }
        }
        return dp[0][sum / 2];
    }

    // Iterate over all possible differences between sums of two halves
    for (int diff = -sum / 2; diff <= sum / 2; diff++) {
        if (checkDifference(diff, new int[diff + 1][sum / 2 + 1], nums)) {
            return true;
        }
    }
    return false;
}

boolean checkDifference(int val, int[][] dp, int[] nums) {
        for (int i = dp.length - 1; i >= 0; i--) {
            if (val < 0) dp[i][val] = false; // If value is negative, it's impossible
            else if (val == 0) dp[i][val] = true; // If value is zero, it's possible
            else {
                dp[i][val] = dp[i + 1][val] || dp[i + 1][val - nums[i]];
            }
        }
        return dp[0][sum / 2];
    }

public boolean splitArraySameAverage(int[] nums) {
    if (nums.length < 2) return false;

    // Calculate the total sum of the array
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    double average = (double) sum / nums.length;

    // Try cutting the array at each possible starting point
    for (int i = 1; i < nums.length; i++) {
        // Check if the prefix sum up to i is divisible by the average
        if ((sum - nums[i]) % i == 0) {
            int suffixSum = (sum - nums[i]) / i;
            // Ensure the suffix sum is the average of the rest of the array
            if (suffixSum * (nums.length - i) == sum - nums[i]) {
                return true;
            }
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    targetSum = totalSum / 2;
    int sum = 0;
    if (totalSum % 2 != 0) {
        return false;
    }
    dp = new boolean[nums.length][targetSum + 1];
    sum = 0;
    dp[0][0] = true; // Base case: empty array has average 0

    for (int i = 1; i < nums.length; i++) {
        sum += nums[i];
        for (int j = targetSum; j >= nums[i]; j--) {
            // Check for dp[i-1][j] and dp[i-1][j - nums[i]]
            if (dp[i - 1][j - nums[i]] || (dp[i - 1][j] != false && (nums[i] * 2 == j))) {
                dp[i][j] = true;
            }
        }
    }

    return dp[nums.length - 1][targetSum];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n <= 2) return 0;

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n < 2) return 0; // No cost needed if there are only zero or one steps

    int[] dp = new int[n]; // Initialize dp array to store minimum cost to reach step i
    dp[0] = cost[0]; // Base case: cost to reach step 0 is the cost of step 0
    dp[1] = cost[1]; // Base case: cost to reach step 1 is the cost of step 1

    // Fill dp array by considering the minimum cost to reach step i
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    // The minimum cost to reach the top of the stairs is the minimum between the last two steps
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }

    if (cost.length == 1) {
        return cost[0];
    }

    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 2], dp[i - 1]) + cost[i];
    }

    return Math.min(dp[cost.length - 2], dp[cost.length - 1]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n <= 1) return 0;
    if (n == 2) return Math.min(cost[0], cost[1]);
    for (int i = 2; i < n; ++i) {
        cost[i] += Math.min(cost[i-1], cost[i-2]);
    }
    return Math.min(cost[n-1], cost[n-2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];

    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = cost[0];

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i - 1];
    }

    return dp[n];
}

