public boolean hasAllCodes(String s, int k) {
    boolean[] mask = new boolean[1 << k];
    for (int i = 0; i < k; i++) {
        for (char c : s.toCharArray()) {
            mask[i << 1 | c - '0'] = true;
        }
    }
    for (boolean m : mask) {
        if (!m) return false;
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    int totalCodes = 1 << k;
    int uniqueCodes = 0;

    for (int i = 0; i <= s.length() - k; i++) {
        int currentCode = Integer.valueOf(s.substring(i, i + k), 2);
        uniqueCodes |= (1 << currentCode);
    }

    return uniqueCodes == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int numUniqueCodes = (1 << k); // Number of unique binary strings of length k
    if (n < numUniqueCodes) {
        return false; // Not enough length in s to form all unique codes
    }
    boolean[] seen = new boolean[numUniqueCodes]; // Array to track availability of each unique code
    for (int i = 0; i <= n - k; i++) {
        int uniqueCode = 0;
        for (int j = i; j < i + k; j++) {
            uniqueCode = (uniqueCode << 1) | (s.charAt(j) - '0');
        }
        if (seen[uniqueCode]) {
            return false; // Duplicate code found
        }
        seen[uniqueCode] = true;
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    Set<String> seen = new HashSet<>();
    for(int i=0; i<s.length(); i++){
        if(i+k > s.length() return false;
        String sub = s.substring(i, i+k);
        if(!seen.contains(sub)){
            seen.add(sub);
            if(seen.size() == 1<<k) return true;
        }
    }
    return false;
}

