  int left = 0, right = 0;
  for (char c : s.toCharArray()) {
    if (c == '(') left++;
    else right++;
    // If we have more right brackets than left ones, we need to insert '('
    if (right > left) left++;
  }
  // After processing all characters, if we still have left brackets left, we need to insert the remaining ones
  return left + right;
}

public int minInsertions(String s) {
    int balance = 0; // Tracks the balance of parentheses
    int insertions = 0; // Counts the number of needed insertions

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance++;
        } else { // s.charAt(i) == ')'
            if (balance > 0) {
                balance--; // Closing bracket balances opening bracket
            } else {
               insertions++; // Opening bracket needs to be paired with closer
                balance++; // Pairs the opening bracket stack back up
            }
        }
    }

    // If there are remaining opening brackets, needs to be inserted at the beginning
    insertions += balance > 0 ? balance : 0;

    return insertions;
}

public int minInsertions(String s) {
