    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance--;
            if (balance < 0) {
                insertions++;
                balance++;
            }
        } else {
            balance++;
            if (balance < 0) {
                insertions++;
                balance++;
            }
        }
    }
    return insertions + balance;
}

