    int balance = 0, left = 0, right = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            left++;
            balance++;
        } else {
            right++;
            if (balance > 0) balance--;
            else left++;
        }
    }
    return left + right;
}

