public int maxAbsoluteSum(int[] nums) {
    int res = Integer.MIN_VALUE;
    int min = 0;
    int max = 0;

    for (int num : nums) {
        min = Math.min(min + num, num);
        max = Math.max(max + num, num);
        res = Math.max(res, Math.abs(max));
        res = Math.min(res, Math.abs(min));
    }

    return res;
}

