    for (int num : nums) {
        total_max = Math.max(total_max + num, num);
        max_sum = Math.max(max_sum, total_max);

        total_min = Math.min(total_min + num, num);
        min_sum = Math.min(min_sum, total_min);

        result = Math.max(result, Math.max(max_sum, -min_sum));
    }

    return result;
}

