public int findMinFibonacciNumbers(int k) {
    if (k <= 2) return k;
    int[] fib = {1, 1};
    while (fib[fib.length - 1] + fib[fib.length - 2] <= k) {
        fib = Arrays.copyOf(fib, fib.length + 1);
        fib[fib.length - 2] += fib[fib.length - 1];
    }
    int count = 0;
    while (k > 0) {
        count++;
        k -= fib[fib.length - count];
    }
    return count;
}

