    while(i < j) {
        if(s.charAt(i) == Character.toUpperCase(s.charAt(j)) || s.charAt(j) == Character.toUpperCase(s.charAt(i))) {
            s = s.substring(0, i) + s.substring(i + 1); 
            i--;
            j--;
        } else {
            i++;
        }
    }
    return s;
