public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) return 0;

    Set<String> seen = new HashSet<>();
    int maxLength = 0;

    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (!seen.contains(prefix)) {
            seen.add(prefix);
            maxLength = Math.max(maxLength, maxUniqueSplit(s.substring(i)));
        }
    }

    return maxLength + 1;
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int maxSubstrings = 0;

    for (int length = 1; length <= n; length++) {
        String prefix = s.substring(0, length);
        Set<String> seenSubstrings = new HashSet<>();
        seenSubstrings.add(prefix);

        boolean canConstruct = true;
        for (int i = length; i < n; i++) {
            String suffix = s.substring(i, i + length);
            if (!seenSubstrings.add(suffix)) {
                canConstruct = false;
                break;
            }
        }

        if (canConstruct) {
            maxSubstrings = Math.max(maxSubstrings, seenSubstrings.size());
        }
    }

    return maxSubstrings;
}

public int maxUniqueSplit(String s) {
    int maxUnique = 0;
    Set<String> usedSubstrings = new HashSet<>();

    for (int i = 0; i < s.length(); i++) {
        String currentSub = s.substring(i);
        if (!usedSubstrings.contains(currentSub)) {
            usedSubstrings.add(currentSub);
            maxUnique++;
        } else {
            break;
        }
    }

    return maxUnique;
}

public int maxUniqueSplit(String s) {
        return maxUniqueSplit(s, new HashSet<>());
    }

private int maxUniqueSplit(String s, Set<String> used) {
        if (s.isEmpty()) {
            return 0;
        }

        int max = 0;
        for (int i = 1; i <= s.length(); i++) {
            String curr = s.substring(0, i);
            if (!used.contains(curr)) {
                used.add(curr);
                max = Math.max(max, 1 + maxUniqueSplit(s.substring(i), used));
                used.remove(curr);
            }
        }

        return max;
    }

public int maxUniqueSplit(String s) {
    List<String> current = new ArrayList<>();
    int maxLength = 0;
    backtrack(s, 0, current, maxLength);
    return maxLength;
}

private void backtrack(String s, int start, List<String> current, int maxLength) {
    if (start == s.length()) {
        maxLength = Math.max(maxLength, current.size());
        return;
    }

    for (int i = start; i < s.length(); i++) {
        String substring = s.substring(start, i + 1);
        if (current.contains(substring)) continue;
        current.add(substring);
        backtrack(s, i + 1, current, maxLength);
        current.remove(current.size() - 1);
    }
}

