public String getSmallestString(int n, int k) {
    String result = "";
    for (int i = 0; i < n; i++) {
        int value = Math.min(k - i, 25); // Ensure the value does not overflow the character 'z'
        result += (char) ('a' + value);
        k -= value;
    }
    return result;
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int currentChar = (k - 1) % 26 + 1; // Convert k-1 to a character in the alphabet
    for (int i = n; i > 0; i--) {
        result.insert(0, (char) (currentChar + 'a' - 1));
        if (k > 0) {
            k -= currentChar - 1;
        }
        currentChar = (k - 1) % 26 + 1; // Update current character for the next digit
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    String smallestString = "";
    for (int i = 1; k > 0; i++) {
        if (k >= i) {
            smallestString += (char) (i + 96); // 'a' equals 97, so 'a' + (0-8) equals 97-97 = 0, hence 'a'
            k -= i;
        } else {
            smallestString += 'a';
            k -= 1;
        }
    }
    return smallestString;
}

public String getSmallestString(int n, int k) {
    Character[] array = new Character[n];
    if (k <= 26) {
        for (int i = 0; i < n; i++) {
            array[i] = 'a' + k % 26;
            k = k / 26 - 1;
        }
    } else if (k <= 52) {
        for (int i = 0; i < n; i++) {
            array[i] = 'a' + k % 26;
            k = k / 26 - 1;
        }
    }
    return new String(array);
}

public static double calculateProbability(int n) {
    if (n <= 2) {
        return 1.0;
    }
    int lastWinner = 0;
    int lastLoser = 1;
    for (int i = 3; i <= n; i++) {
        int newLastWinner = lastLoser;
        int newLastLoser = (lastWinner + lastLoser) % 2;
        lastWinner = newLastWinner;
        lastLoser = newLastLoser;
    }
    return (double) lastWinner / n;
}

