public static int singleNumber(int[] nums) {
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            bitCount[i] += (num >> i) % 2;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if (bitCount[i] % 3 == 1) {
            result += (1 << i);
        }
    }
    return result;
