public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    for (int i = 0; i < 10; i++) {
        if (i <= high && i >= low) {
            steppingNumbers.add(i);
            findSteppingNumbersHelper(steppingNumbers, String.valueOf(i), high);
        }
    }
    return steppingNumbers;
}

private static void findSteppingNumbersHelper(List<Integer> steppingNumbers, String current, int high) {
    StringBuilder sb = new StringBuilder(current);
    int lastDigit = sb.charAt(sb.length() - 1) - '0';
    if (lastDigit >= 1 && sb.length() <= high.length()) {
        steppingNumbers.add(Integer.parseInt(sb.toString()));
        findSteppingNumbersHelper(steppingNumbers, sb.append(lastDigit - 1).toString(), high);
        if (lastDigit <= 8 && sb.length() <= high.length()) {
            steppingNumbers.add(Integer.parseInt(sb.toString()));
            findSteppingNumbersHelper(steppingNumbers, sb.append(lastDigit + 1).toString(), high);
        }
    }
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    Queue<Integer> queue = new LinkedList<>();
    queue.add(low);

    while (!queue.isEmpty()) {
        int current = queue.poll();

        if (current >= low && current <= high) {
            result.add(current);
        }

        int prev = current % 10;

        if (prev == 0 && current > 0) {
            queue.add(current + 1);
        } else if (prev == 9 && current > 0) {
            queue.add(current - 1);
        } else if (prev > 0 && current > 0 && (prev - 1) < 10) {
            queue.add(current - 1);
        }
        if (prev < 9 && current > 0 && (prev + 1) < 10) {
            queue.add(current + 1);
        }
    }

    result.sort(Integer::compare);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    HashSet<Integer> numbers = new HashSet<>();

    maskAndIterate(low, high, 0, numbers);

    return new ArrayList<>(numbers);
}

private static void maskAndIterate(int low, int high, int mask, HashSet<Integer> numbers) {
    if (mask >= low && mask <= high && !numbers.contains(mask)) {
        numbers.add(mask);
        for (int i = 0; i < 10; i++) {
            int newNum = mask * 10 + i;
            if ((i == 0 && mask == 0) || (i != 0 && Math.abs(newNum % 2) != Math.abs((mask % 2) + i % 2))) {
                continue;
            }
            maskAndIterate(low, high, newNum, numbers);
        }
    }
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    for (int num = Math.max(0, low); num <= high; num++) {
        if (isStepping(num)) {
            result.add(num);
        }
    }
    return result;
}

private static boolean isStepping(int num) {
    String numStr = Integer.toString(num);
    for (int i = 1; i < numStr.length(); i++) {
        if (Math.abs(Integer.parseInt(numStr.substring(i - 1, i)) - Integer.parseInt(numStr.substring(i, i + 1))) != 1) {
            return false;
        }
    }
    return true;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    findSteppingNumbersInternal( steppingNumbers, low, high, 0);
    return steppingNumbers;
}

private static void findSteppingNumbersInternal(List<Integer> numbers, int low, int high, int currentNumber) {
    if (currentNumber == 0 || currentNumber < low || currentNumber > high) {
        return;
    }
    if (currentNumber >= low && currentNumber <= high) {
        numbers.add(currentNumber);
    }
    int next = currentNumber * 10;
    if (next >= low && next <= high) {
        numbers.add(next + 1);
        if (next >= low && next <= high)
            numbers.add(next - 1);
        if (next >= low && next <= high)
            numbers.add(next + 0);
        if (next >= low && next <= high)
            numbers.add(next - 0);
        if (next >= low && next <= high)
            numbers.add(next + 1);
        if (next >= low && next <= high)
            numbers.add(next - 1);
    }
    findSteppingNumbersInternal(numbers, low, high, next + 1);
    findSteppingNumbersInternal(numbers, low, high, next - 1);
    // Add 0 to the streak of increasing/decreasing by 1
    findSteppingNumbersInternal(numbers, low, high, next + 0);
    findSteppingNumbersInternal(numbers, low, high, next - 0);
}

public static int countDigitOne(int n) {
    int count = 0;
    for (int i = 0; i <= n; i++) {
        count += countDigit(i);
    }
    return count;
}

private static int countDigit(int x) {
    if (x == 1) return 1;
    if (x == 0) return 0;
    int ans = 0;
    for (int d = 1; x >= 10; d *= 10) {
        int tens = x / d;
        int curDigit = x % d;
        if (curDigit == 1) ans += (10 * (tens - 1) + d);
        else ans += 10 * tens;
    }
    return ans;
}

public static int countDigitOne(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        count += countDigitOneHelper(i);
    }
    return count;
}

private static int countDigitOneHelper(int n) {
    if (n == 0) return 0;
    int power = (int) Math.floor(Math.log10(n));
    int digit = n / (int) Math.pow(10, power);
    if (digit == 1) {
        return (n % (int) Math.pow(10, power)) + 1 + countDigitOneHelper(n % (int) Math.pow(10, power) - 1);
    } else if (digit > 1) {
        return (int) Math.pow(10, power) + (10 - digit) * countDigitOneHelper(n % (int) Math.pow(10, power));
    } else {
        return (int) Math.pow(10, power) + countDigitOneHelper(n % (int) Math.pow(10, power) - 1);
    }
}

public static int countDigitOne(int n) {
    int cnt = 0;
    for (int i = 0; i <= n; i++) {
        cnt += helper(i, 0, 0);
    }
    return cnt;
}

private static int helper(int num, int power, int prev) {
    if (num == 0) return 0;
    int digit = num % 10;
    if (digit == 1) return helper(num / 10, power + 1, 1) + (num / 10 + 1) * Math.pow(10, power) + helper(num / 10, power, 0);
    else return helper(num / 10, power + 1, 0) + (num / 10 + 1) * Math.pow(10, power);
}

