public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }

    int count = 0;
    int i = 1;
    while (n >= i) {
        int tens = i * 10;
        int current = n / tens;
        count += current * i;
        if (current > 0) {
            count += min(n % tens, i) + 1;
        }
        i *= 10;
    }
    return count;
}

