public static int longestLine(int[][] mat) {
    int m = mat.length, n = mat[0].length;
    int maxLength = 0;
    int[][] dp = new int[m][n];

    // Bottom-up approach to fill the DP array
    for (int i = m - 1; i >= 0; i--) {
        for (int j = n - 1; j >= 0; j--) {
            // If the current cell is 1
            if (mat[i][j] == 1) {
                // Initialize maxLength to 1
                maxLength = 1;
                // Check if the cell above is 1, then the continuity continues diagonally
                if (i + 1 < m && mat[i + 1][j] == 1) {
                    dp[i][j] += dp[i + 1][j] + 1;
                }
                // Check if the cell to the left is 1, then the continuity continues horizontally
                if (j + 1 < n && mat[i][j + 1] == 1) {
                    dp[i][j] += dp[i][j + 1] + 1;
                }
                // Check if the cell diagonally up-left is 1, then the continuity continues diagonally
                if (i + 1 < m && j + 1 < n && mat[i + 1][j + 1] == 1) {
                    dp[i][j] += dp[i + 1][j + 1] + 1;
                }
                // Check if the cell diagonally down-left is 1, then the continuity continues diagonally
                if (i - 1 >= 0 && j + 1 < n && mat[i - 1][j + 1] == 1) {
                    dp[i][j] += dp[i - 1][j + 1] + 1;
                }

                // Update maxLength with the current cell's value
                maxLength = Math.max(maxLength, dp[i][j]);
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    // Check horizontal lines
    for (int i = 0; i < rows; i++) {
        int current maxLengthInRow = 0;
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                current maxLengthInRow++;
                maxLength = Math.max(maxLength, current maxLengthInRow);
            } else {
                current maxLengthInRow = 0;
            }
        }
    }

    // Check vertical lines
    for (int j = 0; j < cols; j++) {
        int current maxLengthInColumn = 0;
        for (int i = 0; i < rows; i++) {
            if (mat[i][j] == 1) {
                current maxLengthInColumn++;
                maxLength = Math.max(maxLength, current maxLengthInColumn);
            } else {
                current maxLengthInColumn = 0;
            }
        }
    }

    // Check diagonal lines
    for (int i = 0, j = 0; i < rows && j < cols; i++, j++) {
        int current maxLengthInDiagonal = 0;
        while (i < rows && j < cols && mat[i][j] == 1) {
            current maxLengthInDiagonal++;
            i++;
            j++;
        }
        maxLength = Math.max(maxLength, current maxLengthInDiagonal);
    }

    for (int i = rows - 1, j = 0; i >= 0 && j < cols; i--, j++) {
        int current maxLengthAntidiagonal = 0;
        while (i >= 0 && j < cols && mat[i][j] == 1) {
            current maxLengthAntidiagonal++;
            i--;
            j++;
        }
        maxLength = Math.max(maxLength, current maxLengthAntidiagonal);
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
        if (mat == null || mat.length == 0 || mat[0].length == 0) return 0;

        int maxLength = 0;
        int rowCount = mat.length;
        int colCount = mat[0].length;

        // Check horizontal and vertical lines
        for (int r = 0; r < rowCount; r++) {
            int maxLengthInRow = 0;
            int maxLengthInCol = 0;

            for (int c = 0; c < colCount; c++) {
                if (mat[r][c] == 1) {
                    maxLengthInRow = Math.max(maxLengthInRow + 1, 1);
                    maxLengthInCol = Math.max(maxLengthInCol + 1, 1);
                    maxLength = Math.max(maxLength, maxLengthInRow);
                } else {
                    maxLengthInRow = 0;
                    maxLengthInCol = 0;
                }
            }
        }

        // Check diagonals (top-left to bottom-right)
        for (int d = 0; d < rowCount + colCount - 1; d++) {
            int currMax = 0;
            int r = Math.min(d, rowCount - 1);
            int c = Math.max(0, d - rowCount + 1);

            while (r >= 0 && c < colCount) {
                if (mat[r][c] == 1) {
                    currMax = currMax + 1;
                } else {
                    currMax = 0;
                }
                maxLength = Math.max(maxLength, currMax);
                r--;
                c++;
            }
        }

        // Check diagonals (top-right to bottom-left)
        for (int d = -1; d < rowCount + colCount - 1; d++) {
            int currMax = 0;
            int r = Math.max(0, d + 1);
            int c = Math.min(d, colCount - 1);

            while (r < rowCount && c >= 0) {
                if (mat[r][c] == 1) {
                    currMax = currMax + 1;
                } else {
                    currMax = 0;
                }
                maxLength = Math.max(maxLength, currMax);
                r++;
                c--;
            }
        }

        return maxLength;
    }

public static int longestLine(int[][] mat) {
    int row = mat.length;
    if (row == 0) return 0;

    int col = mat[0].length;
    if (col == 0) return 0;

    int[][] horizontal = new int[row][col];
    int[][] vertical = new int[row][col];
    int[][] diagonal = new int[row][col];
    int[][] antiDiagonal = new int[row][col];

    int maxLength = 0;

    for (int i = 0; i < row; i++) {
        for (int j = 0; j < col; j++) {
            if (mat[i][j] == 1) {
                horizontal[i][j] = j == 0 ? 1 : horizontal[i][j - 1] + 1;
                vertical[i][j] = i == 0 ? 1 : vertical[i - 1][j] + 1;
                diagonal[i][j] =
                                i == 0 || j == 0 ? 1 : diagonal[i - 1][j - 1] + 1;
                antiDiagonal[i][j] =
                                i == row - 1 || j == col - 1 ? 1
                                : antiDiagonal[i + 1][j - 1] + 1;
                maxLength = Math.max(maxLength, Math.max(horizontal[i][j], vertical[i][j]));
                maxLength = Math.max(maxLength, Math.max(diagonal[i][j], antiDiagonal[i][j]));
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length, n = mat[0].length;
    int[][] dp = new int[m][n];
    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = 1; // Single element horizontal
                if (j > 0 && mat[i][j - 1] == 1) {
                    dp[i][j] = dp[i][j - 1] + 1; // Vertical
                }
                if (i > 0 && j > 0 && mat[i - 1][j - 1] == 1) {
                    dp[i][j] = dp[i - 1][j - 1] + 1; // Diagonal
                }
                if (i > 0 && j < n - 1 && mat[i - 1][j + 1] == 1) {
                    dp[i][j] = dp[i - 1][j + 1] + 1; // Anti-diagonal
                }
                maxLength = Math.max(maxLength, dp[i][j]);
            }
        }
    }

    return maxLength;
}

public static String addThousandSeparator(int n) {
