    int[] dp = new int[n];

    // Base case: there is 1 permutation for single-element array if the element itself is a perfect square
    dp[0] = A[0] % Math.sqrt(A[0]) == 0 ? 1 : 0;

    for (int i = 2; i <= n; i++) {
        int count = 0;
        for (int j = 0; j < i; j++) {
            if ((A[i] + A[j]) % Math.sqrt(A[i] + A[j]) == 0 && dp[j] > 0) {
                dp[i] += dp[j];
            }
        }
    }

    return dp[n];
}

public static int squarePermutations(int[] A) {
    int count = 0;

    // Check if the array has less than 2 elements
    if (A.length < 2) return count;

    // Sort the array in ascending order
    Arrays.sort(A);

    // Helper function to generate permutations
    void generatePermutations(int[] A, int start, int end, List<int[]> permutations) {
        if (start == end) {
            permutations.add(A.clone());
            return;
        }

        // Swap the current element with every other element in the array
        for (int i = start; i <= end; i++) {
            swap(A, start, i);
            generatePermutations(A, start + 1, end, permutations);
            swap(A, start, i); // backtrack
        }
    }

    // List to store the square permutations
    List<int[]> squarePermutations = new ArrayList<>();

    // Generate all permutations of the sorted array
    generatePermutations(A, 0, A.length - 1, squarePermutations);

    // Filter out permutations where the sum of adjacent elements is not a perfect square
    for (int[] perm : squarePermutations) {
        boolean isPerfectSquare = true;
        for (int i = 0; i < perm.length - 1; i++) {
            int sum = perm[i] + perm[i + 1];
            if (!isPerfectSquareOf(sum)) {
                isPerfectSquare = false;
                break;
            }
        }
        if (isPerfectSquare) count++;
    }

    return count;
}

