    int n = A.length;
    if (n == 0) return 0;
    long[][] dp = new long[n][n];
    for (int i = 0; i < n; i++) {
        dp[i][i] = 1; // Base case: An array with one element is always a square permutation.
    }

    for (int len = 2; len <= n; len++) {
        for (int start = 0; start <= n - len; start++) {
            for (int mid = start + 1; mid < start + len; mid++) {
                if (isPerfectSquare(A[mid] + A[mid - 1])) {
                    dp[start][start + len - 1] += dp[start][mid - 1] * dp[mid][end];
                }
            }
        }
    }

    return (int) (dp[0][n - 1] % 1000000007); // Return the result modulo 10^9+7 for large numbers.
}

