        while (prevIndex >= 0 && heights[prevIndex] >= heights[i]) {
            prevIndex = leftSmaller[prevIndex];
        }
        leftSmaller[i] = prevIndex;
    }

    // Find the right smaller elements
    rightSmaller[heights.length - 1] = heights.length;
    for (int i = heights.length - 2; i >= 0; i--) {
