public static int[] diagonalOrder(int[][] mat) {
    if (mat.length == 0 || mat[0].length == 0) return new int[0];
    int[] result = new int[mat.length * mat[0].length];
    int row = 0, col = 0;
    int val = 0;
    while (val < result.length) {
        result[val++] = mat[row][col];
        if (row == 0 && col < mat[0].length - 1) {
            col++;
            if (col >= mat[0].length) {
                row++;
                col--;
            }
        } else if (row < mat.length - 1 && col == mat[0].length - 1) {
            row++;
            if (row >= mat.length) {
                row--;
                col++;
            }
        } else if (row == mat.length - 1 && col == 0) {
            row--;
            if (row >= 0) {
                row++;
                col++;
            }
        } else if (col == 0 && row < mat.length - 1) {
            row++;
            col++;
        } else {
            row--;
            col--;
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null | mat.length == 0) return new int[0];

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    // Traverse the diagonal elements
    for (int d = 0; d < rows + cols - 1; d++) {
        int i = d < rows ? 0 : d - rows + 1;
        int j = d < rows ? d : rows - 1;

        while (i < rows && j >= 0) {
            result[index++] = mat[i][j];
            i++;
            j--;
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int len = 0; // To store the total number of elements in the matrix
    for (int i = 0; i < mat.length; i++) { // Traverse through each row
        len += mat[i].length; // Update the total length
    }
    int maxLen = Math.max(mat.length, mat[0].length); // Find the maximum length of any row
    int[] result = new int[len]; // Create an array to store the result

    int count = 0; // Initialize a counter for the result array
    int r = 0, c = 0; // Initialize pointers for row and column

    while (r < mat.length && c < mat[0].length) { // Traverse until all elements are processed
        result[count++] = mat[r][c]; // Add the current element to the result array
        if (r == mat.length - 1 && c < mat[0].length - 1) { // If we have reached the last row
            c++; // Move to the right
        } else if (c == mat[0].length - 1 && r < mat.length - 1) { // If we have reached the last column
            r++; // Move down
        } else if (mat[r][c] % 2 != 0) { // If the index is odd
            while (c < mat[0].length - 1) { // Move right
                result[count++] = mat[r][c++];
            }
            while (r < mat.length - 1) { // Move down
                result[count++] = mat[r++][c];
            }
            r++; // Move down
            c--; // Move up
        } else { // If the index is even
            while (c > 0) { // Move left
                result[count++] = mat[r][c--];
            }
            while (r > 0) { // Move up
                result[count++] = mat[r--][c];
            }
            c++; // Move right
            r++; // Move down
        }
    }
    return result; // Return the result array
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    Deque<int[]> queue = new ArrayDeque<>();
    queue.add(lastElement(mat));
    int[] result = new int[rows * cols];

    int index = 0;
    while (!queue.isEmpty()) {
        int size = queue.size();
        for (int i = 0; i < size; i++) {
            int[] current = queue.poll();
            result[index++] = current[0];

            if (current[0] == 0) {
                int right = rightMost(current);
                if (right != null) {
                    queue.offer(right);
                }
            } else if (current[0] == rows - 1) {
                int left = leftMost(current);
                if (left != null) {
                    queue.offer(left);
                }
            } else if (current[1] == 0) {
                int down = downMost(current);
                if (down != null) {
                    queue.offer(down);
                }
            } else {
                int up = upMost(current);
                if (up != null) {
                    queue.offer(up);
                }
            }
        }
    }

    return result;
}

private static int[] lastElement(int[][] mat) {
    int row = mat.length - 1;
    int col = mat[0].length - 1;
    return new int[] {row, col};
}

private static int[] rightMost(int[] current) {
    int row = current[0];
    int col = current[1];
    if (col == mat[0].length - 1) {
        return null;
    }
    return new int[] {row, col + 1};
}

private static int[] leftMost(int[] current) {
    int row = current[0];
    int col = current[1];
    if (col == 0) {
        return null;
    }
    return new int[] {row, col - 1};
}

private static int[] downMost(int[] current) {
    int row = current[0];
    int col = current[1];
    if (row == mat.length - 1) {
        return null;
    }
    return new int[] {row + 1, col};
}

private static int[] upMost(int[] current) {
    int row = current[0];
    int col = current[1];
    if (row == 0) {
        return null;
    }
    return new int[] {row - 1, col};
}

public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;
    int totalElements = rows * cols;
    int[] result = new int[totalElements];
    int row = 0;
    int col = 0;
    int direction = 1; // 1 for right, -1 for left

    for (int i = 0; i < totalElements; i++) {
        result[i] = mat[row][col];
        int newRow = row + (direction == 1 ? 1 : -1);
        int newCol = col + (direction == 1 ? 0 : 1);

        if (newRow < 0 || newRow >= rows || newCol < 0 || newCol >= cols) {
            direction *= -1; // Change direction when boundary is reached
            newRow += direction;
            newCol -= direction;
        }

        row = newRow;
        col = newCol;
    }

    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 9) {
        return -1; // Already the smallest integer greater than n that can be formed using the digits of n.
    }

    int[] digits = new int[10];
    int originalN = n;
    while (originalN != 0) {
        digits[originalN % 10]++;
        originalN /= 10;
    }

    int smallest = 0;
    for (int i = 9; i >= 0; i--) {
        if (digits[i] > 0) {
            smallest = i * (int) Math.pow(10, digits.length - i - 1);
            digits[i]--;
            break;
        }
    }

    for (int i = 0; i < 10; i++) {
        while (digits[i]-- > 0) {
            smallest = smallest * 10 + i;
        }
    }

    return smallest > n ? smallest : -1;
}

public static int findSmallestInteger(int n) {
    if (n < 0) {
        return -1; // Negative numbers cannot be rearranged to form a new integer.
    }

    // Convert the integer to a list of digits.
    List<Integer> digits = new ArrayList<>();
    while (n > 0) {
        digits.add(n % 10);
        n /= 10;
    }

    // Sort the digits in ascending order.
    Collections.sort(digits);

    // Find the index of the first non-increasing element from the end.
    int index = digits.size() - 1;
    while (index > 0) {
        if (digits.get(index) > digits.get(index - 1)) {
            break;
        }
        --index;
    }

    // If all digits are in ascending order, no valid rearrangement exists.
    if (index == 0) {
        return -1;
    }

    // Find the smallest digit that is larger than the element at index.
    int right = index;
    while (right < digits.size() && digits.get(right) <= digits.get(index - 1)) {
        right++;
    }

    // Swap the two elements.
    Collections.swap(digits, index - 1, right);

    // Reverse the digits from the index to the end.
    Collections.reverse(digits, index);

    // Convert the list of digits back to an integer.
    int result = 0;
    for (int digit : digits) {
        result = result * 10 + digit;
    }

    return result;
}

public static int findSmallestInteger(int n) {
    // Convert the integer to a character array
    char[] digits = String.valueOf(n).toCharArray();

    // Sort the array in decreasing order
    Arrays.sort(digits);

    // Find the first position where the digits are not in ascending order
    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Swap the digits at the two positions
            char temp = digits[i];
            digits[i] = digits[i + 1];
            digits[i + 1] = temp;

            // Sort the rest of the array in ascending order
            Arrays.sort(digits, i + 1, digits.length);
            break;
        }
    }

    // Convert the sorted array back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // Return -1 if no valid rearrangement is found
    }
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int maxLength = digits.length;
    for (int i = maxLength - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            for (int j = maxLength - 1; j > i; j--) {
                if (digits[j] > digits[i]) {
                    char temp = digits[i];
                    digits[i] = digits[j];
                    digits[j] = temp;
                    Arrays.sort(digits, i + 1, maxLength);
                    return Integer.parseInt(new String(digits));
                }
            }
        }
    }
    return -1;
}

public static int findSmallestInteger(int n) {
    if (n < 10) {
        return -1; // There are no integers greater than 1 without rearrangement
    }

    int decreasingTail = -1, increasingHead = -1;
    for (int i = n; i > 0; i /= 10) {
        int digit = i % 10;
        if (digit > n % 10) {
            if (decreasingTail == -1) {
                decreasingTail = digit;
            } else {
                // Found a smaller digit to replace to get smaller integers
                return Integer.valueOf(digits(0, decreasingTail) + "1" + digits(decreasingTail + 1, digits.length()));
            }
        }
        if (digit < n % 10) {
            increasingHead = digit;
        }
    }

    if (decreasingTail == -1) {
        return -1; // No way to make a number smaller than n with rearrangement
    }

    // Replace the first occurrence of decreasingTail with increasingHead
    int[] digits = digits(n);
    int index = -1;
    for (int i = 0; i < digits.length; i++) {
        if (digits[i] == decreasingTail) {
            index = i;
            break;
        }
    }
    int temp = digits[index];
    digits[index] = digits[increasingHead];
    digits[increasingHead] = temp;

    return Integer.valueOf(digits.join(""));
}

private static char[] digits(int start, int end) {
    char[] arr = new char[end - start];
    int count = 0;
    for (int i = start; i < end; i++) {
        arr[count++] = (char) (i + '0');
    }
    return arr;
}

