        String prefix = String.format("%0" + i + "d", Math.min(i, n - i));
        String suffix = reverse(prefix);
        String center = prefix + suffix;
        result.add(center);
    }

    return result;
}

private static String reverse(String s) {
    StringBuilder sb = new StringBuilder(s);
    return sb.reverse().toString();
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n == 1) return List.of("0", "1", "8");
    List<String> res = new ArrayList<>();
    for (int i = 0; i < n; i++) res.add("0");

    for (int i = 0; i < n; i += 2) {
        int l = i % 2;
        int r = (n - 1) - i;
        int center = i / 2;

        String pre = center == 0 ? "" : res.get(center - 1);
        String mid = res.get(center);
        String suf = res.get(center + 1);

        if (l == 1) res.set(center, "9" + mid + '0' + s);
        else res.set(center, pre + mid + suf);
    }

    return res;
}

