private static boolean isCenterSymmetric(String numStr) {
        int left = 0;
        int right = numStr.length() - 1;
        while (left < right) {
            if (numStr.charAt(left) != numStr.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }

public static List<String> centerSymmetricNumbers(int n) {
    List<String> centerSymmetricNumbers = new ArrayList<>();
    for (int i = 0; i < Math.pow(2, n); i++) {
        int originalNumber = toBinary(i);
        int centerPosition = (n / 2);
        String centerSymmetricalNumber = leftPad(String.valueOf(originalNumber), centerPosition, '0').equals(
                rightPad(String.valueOf(originalNumber), centerPosition, '0'))
            ? String.valueOf(originalNumber)
            : String.valueOf(reverseNumber(originalNumber));
        centerSymmetricNumbers.add(centerSymmetricalNumber);
    }
    return centerSymmetricNumbers;
}

private static int toBinary(int number) {
    StringBuilder binaryString = new StringBuilder();
    while (number > 0) {
        binaryString.insert(0, number % 2);
        number /= 2;
    }
    return Integer.parseInt(binaryString.toString(), 2);
}

private static String reverseNumber(int number) {
    StringBuilder reversed = new StringBuilder();
    while (number > 0) {
        reversed.append(number % 10);
        number /= 10;
    }
    return reversed.toString();
}

private static String leftPad(String string, int length, char fillChar) {
    int paddingSize = length - string.length();
    if (paddingSize > 0) {
        return String.format("%0" + paddingSize + "s", string).replace(' ', fillChar);
    }
    return string;
}

private static String rightPad(String string, int length, char fillChar) {
    int paddingSize = length - string.length();
    if (paddingSize > 0) {
        return string.concat(String.format("%0" + paddingSize + "s", ""));
    }
    return string;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("The input array must contain exactly 3 points.");
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Calculate the slopes between all pairs of points
    double slope1 = (y2 - y1) / (x2 - x1);
    double slope2 = (y3 - y2) / (x3 - x2);
    double slope3 = (y1 - y3) / (x1 - x3);

    // Check if the slopes between any pair of points are not equal
    return slope1 != slope2 && slope1 != slope3 && slope2 != slope3;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3 || points == null) {
        return false;
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if the points are collinear
    if ((y2 - y1) * (x3 - x1) == (y3 - y1) * (x2 - x1)) {
        return false;
    }

    // Check if the points form a boomerang
    return true;
}

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1], x2 = points[1][0], y2 = points[1][1], x3 = points[2][0], y3 = points[2][1];

    // Calculate the area of the triangle formed by the points using the determinant formula
    int area = x2 * (y3 - y1) + y2 * (x1 - x3) + x3 * (y1 - y2);

    // If the area is non-zero, the points form a triangle, and it is not a boomerang
    return area != 0;
}

public static boolean isBoomerang(int[][] points) {
    int dx1 = points[1][0] - points[0][0];
    int dy1 = points[1][1] - points[0][1];
    int dx2 = points[2][0] - points[0][0];
    int dy2 = points[2][1] - points[0][1];

    return dx1 * dy2 != dx2 * dy1;
}

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Check the condition for a triangle with vertices A, B, and D
    return (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) != 0;
}

public static int findNthUglyNumber(int n) {
    int[] factors = {5, 3, 2};
   PriorityQueue<Long> heap = new PriorityQueue<>();
    Set<Long> visited = new HashSet<>();
    heap.offer(1L);
    visited.add(1L);

    int uglyCount = 1;
    long num;

    for (int i = 0; i < n; i++) {
        num = heap.poll();

        for (int factor : factors) {
            long newNum = num * factor;
            if (visited.add(newNum)) {
                heap.offer(newNum);
            }
        }

        uglyCount++;
    }

    return Integer.parseInt(String.valueOf(num));
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) return 0;
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i = 0, j = 0, k = 0;
    int[] factors = {2, 3, 5};
    for (int i = 1; i < n; i++) {
        int min = Math.min(uglyNumbers[i - 1] * factors[0],
                           Math.min(uglyNumbers[i - 1] * factors[1],
                                    uglyNumbers[i - 1] * factors[2]));
        uglyNumbers[i] = min;
        if (uglyNumbers[i] == uglyNumbers[i - 1] * factors[0]) i++;
        if (uglyNumbers[i] == uglyNumbers[i - 1] * factors[1]) j++;
        if (uglyNumbers[i] == uglyNumbers[i - 1] * factors[2]) k++;
    }
    return uglyNumbers[n - 1];
}

