    if (n <= 0) return 0;
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int nextMultipleOf2 = 2, nextMultipleOf3 = 3, nextMultipleOf5 = 5;

    for (int i = 1; i < n; i++) {
        int min = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        ugly[i] = min;

        if (min == nextMultipleOf2) i2++;
        if (min == nextMultipleOf3) i3++;
        if (min == nextMultipleOf5) i5++;

        nextMultipleOf2 = ugly[i2] * 2;
        nextMultipleOf3 = ugly[i3] * 3;
        nextMultipleOf5 = ugly[i5] * 5;
    }

    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    int maxEnergy = 0;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    // Check the last substring
    maxEnergy = Math.max(maxEnergy, currentEnergy);

    return maxEnergy;
}

public static int calculateEnergy(String s) {
    int maxEnergy = 0;
    int currentEnergy = 1;
    char lastChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        if (currentChar == lastChar) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
        lastChar = currentChar;
    }

    maxEnergy = Math.max(maxEnergy, currentEnergy);

    return maxEnergy;
}

public static int calculateEnergy(String s) {
    int maxLen = 1;
    int currentLen = 1;
    int startIndex = 0;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
                startIndex = i - currentLen + 1;
            }
            currentLen = 1;
        }
    }

    // Check the last sequence of the string
    if (currentLen > maxLen) {
        maxLen = currentLen;
        startIndex = s.length() - currentLen + 1;
    }

    return maxLen;
}

public static int calculateEnergy(String s) {
    int left = 0;
    int maxEnergy = 0;
    int currentEnergy = 0;

    for (int right = 0; right < s.length(); right++) {
        if (s.charAt(right) == s.charAt(left)) {
            currentEnergy++;
        } else {
            left = right;
            currentEnergy = 1;
        }
        maxEnergy = Math.max(currentEnergy, maxEnergy);
    }

    return maxEnergy;
}

public static int calculateEnergy(String s) {
    int energy = 0;
    int maxEnergy = 1;
    char currentChar = s.charAt(0);
    boolean isSingle = true;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            isSingle = true;
            maxEnergy = Math.max(maxEnergy, i + 1 - energy);
        } else {
            if (!isSingle) {
                energy = i;
            }
            isSingle = false;
            currentChar = s.charAt(i);
        }
    }

    if (!isSingle) {
        energy = s.length() - 1;
    }

    return maxEnergy;
}

