}

private static void dfs(int cur, int n, List<Integer> result) {
    if (cur > n) {
        return;
    }

    result.add(cur);
    for (int i = 0; i <= 9; i++) {
        dfs(cur * 10 + i, n, result);
    }
}

public static List<Integer> lexicalOrder(int n) {
