    _dfs(n, 0, result);
    return result;
}

private static void _dfs(int n, int current, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int i = current * 10; i < current * 10 + 10 && i <= n; i++) {
        _dfs(n, i, result);
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for(int i = 1; i <= 9; i++){
        process(i, 1, n, result);
    }
    return result;
}

private static void process(int num, int curNum, int n, List<Integer> result) {
    if (curNum > n) return;
    result.add(curNum);
    for(int i = 0; i <= 9; i++){
        int next = curNum * 10 + i;
        if (next <= n){
            process(num, next, n, result);
        }
    }
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueSet = new HashSet<>();
    for (int num : nums) {
        uniqueSet.add(num);
    }
    return uniqueSet.stream().reduce(0, Integer::sum);
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    Set<Integer> uniqueElements = new HashSet<>();
    for (int num : nums) {
        uniqueElements.add(num);
    }

    int sum = 0;
    for (int num : uniqueElements) {
        sum += num;
    }

    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    // Create a HashMap to store counts of numbers
    Map<Integer, Integer> countMap = new HashMap<>();

    // Count occurrences of each number
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }

    // Calculate sum of unique elements
    int uniqueSum = 0;
    for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            uniqueSum += entry.getKey();
        }
    }

    return uniqueSum;
}

