public static int minPerfectSquareSum(int n) {
        Stack<Integer> stack = new Stack<>();
        if (n <= 0) return 0;

        for (int i = 1; i <= n; i++) {
            stack.push(i);
        }

        while (!stack.isEmpty() && n > 0) {
            final int num = stack.pop();

            while (n - num > 0) {
                stack.push(n - num);
                n = n - num;
            }
        }

        return stack.size();
    }

public static String reverseWords(String s) {
    // This method splits the string by spaces, reverses each word, and then joins them back together with spaces.
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        String reversedWord = new StringBuilder(word).reverse().toString();
        result.append(reversedWord).append(" ");
    }

    // Remove the trailing space
    return result.toString().trim();
}

public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();
    String[] words = s.split(" ");
    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        reversedWord.reverse();
        if (result.length() > 0) {
            result.append(" ");
        }
        result.append(reversedWord);
    }
    return result.toString();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversed = new StringBuilder();

    for (String word : words) {
        char[] chars = word.toCharArray();
        for (int i = chars.length - 1; i >= 0; i--) {
            reversed.append(chars[i]);
        }
        reversed.append(" ");
    }

    return reversed.toString().trim();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversedString = new StringBuilder();
    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        for (int i = 0; i < word.length() / 2; i++) {
            char temp = reversedWord.charAt(i);
            reversedWord.setCharAt(i, reversedWord.charAt(word.length() - 1 - i));
            reversedWord.setCharAt(word.length() - 1 - i, temp);
        }
        reversedString.append(reversedWord.toString() + " ");
    }
    return reversedString.toString().trim();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) return s;
    String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
        words[i] = new StringBuilder(words[i]).reverse().toString();
    }
    return String.join(" ", words);
}
